import { configDefaults, defineConfig } from "vitest/config";

/** Minimum percentage of every metric, enforced per source directory. */
const MINIMUM = { lines: 85, statements: 85, functions: 85, branches: 85 };

export default defineConfig({
  test: {
    // tmp/ is scratch space (scripts/write-escaped.ts may create files there): never run it.
    exclude: [...configDefaults.exclude, "tmp/**"],
    coverage: {
      provider: "v8",
      include: ["src/**"],
      exclude: [
        // Generated by antlr-ng (pnpm run gen:parser), checked by pnpm run check:parser.
        "src/generated/**",
        // Process entry (top-level await on process.argv/stdout). Tests reach it only through
        // a child process (tests/unit/cli/spawn.test.ts), which v8 coverage does not see.
        // All its logic lives in src/cli/*, which is covered.
        "src/cli.ts",
      ],
      reporter: ["text", "json-summary"],
      // Glob-keyed thresholds are checked per glob, over all files it matches (not per file).
      // src/tags is checked twice: all of it, and its own files without src/tags/visitors
      // (the "src/tags" row of the text report), so a well-covered visitors folder cannot hide
      // a weak parser.
      thresholds: {
        "src/engine/**": MINIMUM,
        "src/rules/**": MINIMUM,
        "src/tags/**": MINIMUM,
        "src/tags/*.ts": MINIMUM,
      },
    },
  },
});
